mapper.select:
SELECT pc.id
FROM potential_customer pc
WHERE pc.sales_user_id = #{salesUserId}
    AND pc.conversion_status_code = '01'

    /* 오늘 생일인 고객 */
    AND DATE_FORMAT(pc.birth_date, '%m-%d') = DATE_FORMAT(CURDATE(), '%m-%d')

    /* 오늘 이미 웹폼 발송완료된 고객 제외 */
    AND NOT EXISTS (
        SELECT 1
        FROM webform_issuance wi
        WHERE wi.customer_id = pc.id
            AND wi.conversion_status_code = '01'
            AND wi.sales_user_id = #{salesUserId}
            AND wi.webform_status_code = '02'
            AND Date(wi.issued_at) = CURDATE()
    )

SELECT customer_id
FROM webform_issuance
WHERE uuid_token = #{uuidToken}
